{
  "name": "notify-opencode",
  "version": "0.3.1",
  "description": "Notificações do OpenCode no celular via Node-RED — plugin V2 com gatilhos de pergunta, permissão, conclusão e erro, toggle por sessão na TUI e resumo opcional do corpo por IA.",
  "type": "module",
  "private": true,
  "engines": {
    "node": ">=18.0.0"
  },
  "scripts": {
    "flow:apply": "node scripts/apply-nodered-flow.mjs",
    "flow:test": "node scripts/test-send-event.mjs",
    "flow:validate": "node scripts/validate-flow.mjs",
    "test:summary": "node scripts/test-summary.mjs",
    "test": "node scripts/validate-flow.mjs && node scripts/check-hygiene.mjs && node scripts/test-summary.mjs"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Brook-sys/notify-opencode.git"
  },
  "bugs": {
    "url": "https://github.com/Brook-sys/notify-opencode/issues"
  },
  "homepage": "https://github.com/Brook-sys/notify-opencode#readme",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "node-red",
    "nodered",
    "notifications",
    "webhook",
    "automation"
  ],
  "author": "Brook-sys",
  "license": "MIT"
}

{
  "name": "opencode-notify-nodered",
  "version": "0.3.1",
  "description": "OpenCode V2 plugin that pushes session events (question, permission, done, error) to a Node-RED webhook, with a per-session notification toggle in the TUI and an optional AI summary of the notification body.",
  "type": "module",
  "exports": {
    ".": "./index.ts",
    "./tui": "./tui.tsx",
    "./rpc": "./rpc.ts"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.6.6",
    "@opentui/solid": ">=0.6.6",
    "solid-js": ">=1.9.0"
  }
}

{
  "name": "opencode-smoke-log",
  "version": "0.1.0",
  "type": "module",
  "exports": {
    ".": "./index.ts"
  }
}
